// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        assertEq(c.tokenBalance(actor), 0);

        BankLike helper = new BankLike();

        assertEq(c.tokenBalance(address(helper)), 0);

        vm.prank(address(helper));
        c.airDrop();

        assertTrue(c.tokenBalance(address(helper)) == 20);
    }
}

contract BankLike {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
